import {usePreloadedQuery} from 'react-relay'
import type {PreloadedQuery} from 'react-relay'

import type {WelcomeScreenHasPipelinesQuery} from './__generated__/WelcomeScreenHasPipelinesQuery.graphql'
import {hasPipelinesQuery} from './WelcomeScreen.queries'

export function useHasPipelines(queryRef: PreloadedQuery<WelcomeScreenHasPipelinesQuery>) {
  const {pipelinesRest} = usePreloadedQuery(hasPipelinesQuery, queryRef)
  return Boolean(pipelinesRest?.count)
}
