import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'

import {useDarkOrLightTheme} from '../../../../../hooks/theme/useDarkOrLightTheme'
import Routes, {getHref} from '../../../../../routes'
import PageTitle from '../../../../common/PageTitle/PageTitle'
import {RouterButton} from '../../../../common/RouterLink/RouterLink'
import usePermissionCanEditProject from '../../hooks/usePermissionCanEditProject'
import {getAccountRootProjectId, noPermissionToCreateMessage} from '../../PipelinesPages.consts'

import PipelinePreviewDark from './pipeline-preview-dark.svg'
import PipelinePreviewLight from './pipeline-preview-light.svg'

import styles from './WelcomeScreen.module.css'

type Props = {
  hasPipelines?: boolean
}

function WelcomeScreen({hasPipelines}: Props) {
  const rootId = getAccountRootProjectId()
  const canEditProject = usePermissionCanEditProject(rootId)

  let cardTitle = 'Start your first project'
  let cardDescription = "Let's create one to get you started on your pipeline journey."
  let cardButton = 'Create new pipeline'
  let tooltipText = ''

  if (hasPipelines) {
    cardTitle = 'Choose or create your next pipeline'
    cardDescription = ''
    cardButton = 'Create pipeline'
  }

  if (!canEditProject) {
    tooltipText = noPermissionToCreateMessage
  }

  const selectedTheme = useDarkOrLightTheme()
  const PipelinePreview = selectedTheme === Theme.DARK ? PipelinePreviewDark : PipelinePreviewLight

  return (
    <div className={styles.page}>
      <PageTitle className={styles.pageHeading}>{'Welcome to TeamCity Pipelines!'}</PageTitle>
      <div className={styles.card}>
        <div className={styles.createPipeline}>
          <H2 className={styles.createPipelineHeading}>{cardTitle}</H2>
          {cardDescription && <p className={styles.createPipelineDescription}>{cardDescription}</p>}
          <div className={styles.createPipelineButtonWrapper}>
            <Tooltip title={tooltipText} delay={600} popupProps={{offset: 8}}>
              <RouterButton
                primary
                disabled={!canEditProject}
                to={{pathname: getHref(Routes.CREATE_PIPELINE)}}
              >
                <SvgIcon className={styles.createPipelineIcon} icon="add" />
                {cardButton}
              </RouterButton>
            </Tooltip>
          </div>
        </div>
        <div className={styles.previewImage}>
          <PipelinePreview data-ignore-dark-theme-adapter />
        </div>
      </div>
    </div>
  )
}

export default WelcomeScreen
